            image.get('imageId', {}).get('imageDigest') != digest or not isinstance(raw, str) or
            len(raw.encode()) > MANIFEST_LIMIT or 'sha256:' + hashlib.sha256(raw.encode()).hexdigest() != digest):
        raise ValueError('image manifest binding mismatch')
